import{_ as e,o as i,c as n,ag as o}from"./chunks/framework.CrXGS008.js";const u=JSON.parse('{"title":"Repair Station","description":"","frontmatter":{},"headers":[],"relativePath":"pl/repair-station/index.md","filePath":"pl/repair-station/index.md"}'),s={name:"pl/repair-station/index.md"};function t(r,a,c,l,p,d){return i(),n("div",null,[...a[0]||(a[0]=[o(`<h1 id="repair-station" tabindex="-1">Repair Station <a class="header-anchor" href="#repair-station" aria-label="Permalink to &quot;Repair Station&quot;">​</a></h1><p>Wjeżdżasz na stację napraw, wybierasz usługę, a pojazd jest naprawiany na miejscu: silnik, karoseria i opony, z dźwiękiem i iskrami. Cena zależy od uszkodzeń, więc porysowane auto płaci mniej niż wrak. Stacje ustawia się w grze i każde ustawienie edytuje się w grze.</p><h2 id="funkcje" tabindex="-1">Funkcje <a class="header-anchor" href="#funkcje" aria-label="Permalink to &quot;Funkcje&quot;">​</a></h2><ul><li><strong>Trzy usługi od razu</strong>: szybka naprawa (silnik), blacharka (karoseria i opony), pełna naprawa. Nazwę, cenę, czas i naprawiane części możesz zmienić. Zobacz <a href="/pl/repair-station/settings">Ustawienia</a>.</li><li><strong>Cena zależna od uszkodzeń</strong>: cena zależy od uszkodzeń naprawianych części, do minimalnego procentu. Pojazdy bez uszkodzeń są odrzucane.</li><li><strong>Edytor stacji w grze</strong>: utwórz stację tam, gdzie stoisz, przesuń strefę zatrzymania i opcjonalny prop klawiaturą, zapisz. Zobacz <a href="/pl/repair-station/stations">Stacje</a>.</li><li><strong>Mechanicy mają pierwszeństwo</strong>: stacje zamykają się, gdy na służbie jest dość mechaników, a gracze dzwonią do nich.</li><li><strong>Uczciwie i bezpiecznie</strong>: jeden pojazd na stację, kontrola kierowcy i prędkości, płatności potwierdzane przez serwer. Anulowana naprawa jest zwracana na obciążone konto.</li><li><strong>Zniżki dla zawodów</strong>, procent ceny na stację oraz płatność gotówką, z banku lub gotówką, a potem z banku.</li><li><strong>Wszystko w <code>/nay</code></strong>: usługi, ceny, stacje, zawody mechaników, blipy z wizualnym wyborem ikony i koloru.</li><li><strong>API HTTP i webhooki</strong>: historia napraw, statystyki i stacje dla Twojej strony lub bota, wiadomość na Discordzie przy każdej naprawie. Zobacz <a href="/pl/repair-station/api">API i webhooki</a>.</li><li><strong>Rozszerzalność</strong>: inny zasób może zmieniać ceny, zamykać stacje i brać udział w każdej naprawie. Zobacz <a href="/pl/repair-station/api#extensions">Rozszerzenia</a>.</li><li><strong>Sześć języków</strong>: angielski, francuski, hiszpański, portugalski, polski, niemiecki.</li></ul><h2 id="zgodnosc" tabindex="-1">Zgodność <a class="header-anchor" href="#zgodnosc" aria-label="Permalink to &quot;Zgodność&quot;">​</a></h2><ul><li>Frameworki: ESX Legacy, QBCore, QBox, ox_core, wykrywane automatycznie.</li><li>Zależności: oxmysql i <code>nay_lib</code> (dołączony do zakupu).</li></ul><h2 id="instalacja" tabindex="-1">Instalacja <a class="header-anchor" href="#instalacja" aria-label="Permalink to &quot;Instalacja&quot;">​</a></h2><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ensure oxmysql</span></span>
<span class="line"><span>ensure nay_lib</span></span>
<span class="line"><span>ensure nay_repair</span></span></code></pre></div><p>Pełne kroki znajdziesz na stronie <a href="/pl/getting-started">Pierwsze kroki</a>. Następnie nadaj sobie <code>nay_repair.config</code> (lub <code>nay.admin</code>) i otwórz <code>/nay</code>. Trzy stacje są gotowe od razu: Hayes Autos, Sandy Shores i Paleto Bay.</p>`,9)])])}const k=e(s,[["render",t]]);export{u as __pageData,k as default};
